head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.key_edu_partc_id = ""; // PK
scwin.key_isur_cd = ""; // 회사코드
scwin.key_com_abbrv = ""; // 회사명
scwin.key_chrg_tp_cd = ""; // 담당자구분코드
scwin.key_edu_id = ""; // 교육일정코드
scwin.key_chrg_nm = ""; // 선택된참가자명
scwin.key_edu_nm = ""; // 선택과정명
scwin.key_edu_ack_tm = "";
// 화면 리사이징

scwin.gDepCd = js_dep_cd;

// 공시담당자등 교육참가현황(유)

// 자료수정 시 팝업창으로 넘길 데이터

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.libRoundPanel.PanelToGroupBox(panel_1);
        await scwin.setCode();
        await scwin.setYear();
        $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
        scwin.init();
        txb_isur_cd.setValue($c.stf.getQuery(frame.srcUrl, "ISUR_CD"));
        txb_com_abbrv.setValue($c.stf.getQuery(frame.srcUrl, "COM_NM"));
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30618.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    /*
    	var ToDay = new Date();
    	var yyyy = parseInt(ToDay.getYear(), 10);
    	yyyy = yyyy +1; // 박태일 부부장님 요청으로 차년도까지 조회 가능하도록 수정. 2013.08.22 by ldj
    	var str = "^전체";

    	for (var i = yyyy; i >= 2010 ; i--)
    	{
    		str += "," + i + "^" + i;
    	}

    	cmb_YYYY.CBData = str;
     */
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30618.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_MASTER_OnFail
 * @description MASTER On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_MASTER_OnFail = async function() {
    try {
        await $c.win.alert(dts_MASTER);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30618.dts_MASTER_OnFail" });
    }
};

/**
 * @method
 * @name dts_MASTER_OnLoadError
 * @description dts_MASTER 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_MASTER_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_MASTER);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30618.dts_MASTER_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_MASTER_OnLoadCompleted
 * @description dts_MASTER 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_MASTER_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        if (rowcount <= 0) {
            dts_MASTER.removeAll();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30618.dts_MASTER_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        if (colid === 'DISCLS_EDU_CRS_NM') {
            scwin.setVariable(row);
            await scwin.readDisclsEdu();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30618.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onblur
 * @description txb_isur_cd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_isur_cd.getValue() === "") {
            txb_com_abbrv.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30618.txb_isur_cd_onblur" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onfocus
 * @description txb_isur_cd 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30618.txb_isur_cd_onfocus" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onkeyup
 * @description txb_isur_cd 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onkeyup = function() {
    try {
        if (txb_isur_cd.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30618.txb_isur_cd_onkeyup" });
    }
};

/**
 * @method
 * @name img_com_srch_onclick
 * @description img_com_srch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_com_srch_onclick = function() {
    try {
        $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30618.img_com_srch_onclick" });
    }
};

/**
 * @method
 * @name cmb_DEP_CD_onselchange
 * @description cmb_DEP_CD onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_DEP_CD_onselchange = function() {
    try {
        scwin.gDepCd = cmb_DEP_CD.getValue(); // ;.ValueOfIndex("VALUE", cmb_DEP_CD.Index);

        dts_EMP_NO.UseFilter = true;
        dts_EMP_NO.Filter();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30618.cmb_DEP_CD_onselchange" });
    }
};

/**
 * @method
 * @name dts_EMP_NO_OnFilter
 * @description EMP NO On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_EMP_NO_OnFilter = function(row) {
    try {
        if (scwin.gDepCd === "") {
            // 전체일 경우 모두 보여준다.
            return true;
        } else {
            if (dts_EMP_NO.getCellData(row, "dep_cd") === scwin.gDepCd ||
                dts_EMP_NO.getCellData(row, "dep_cd") === "") {
                return true;
            } else {
                return false;
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30618.dts_EMP_NO_OnFilter" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30618.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30618.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30618.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30618.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30618.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else {
            return true;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30618.MxDataSet_com_isur_OnFilter" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF30618.xml", SCREN_PROCS_TP_CD_07, '');
        $c.data.downloadGridViewExcel(grd_Grid, {fileName: "공시교육참가현황", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30618.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name btn_Input_onclick
 * @description 「입력」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Input_onclick = async function() {
    try {
        scwin.resetVariable();
        await scwin.readDisclsEdu();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30618.btn_Input_onclick" });
    }
};

/**
 * @method
 * @name btn_Snd_onclick
 * @description 「공시담당자 교육참가이력 변경」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Snd_onclick = async function() {
    try {
        await scwin.disclsEduHistory();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30618.btn_Snd_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    const sbmOptions = {
        id : "sbm_dts_EMP_NO",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_EMP_NO=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_dts_DEP_CD",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_DEP_CD=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions3 = {
        id : "sbm_dts_edu",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_edu=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name setYear
 * @description set Year 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setYear = async function() {
    const sbmOptions = {
        id : "sbm_dts_year",
        action : "/ListedCompany.do",
        ref : "",
        target : "dts_year=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const minYear = dts_year.getCellData(1, "MIN_YEAR");
    const maxYear = dts_year.getCellData(1, "MAX_YEAR");
    let str = "^전체";
    for (let i = maxYear; i >= minYear; i--) {
        str += "," + i + "^" + i;
    }
    // alert(str);
    cmb_YYYY.CBData = str;

    // default 현재년도
    const ToDay = new Date();
    const yyyy = parseInt(ToDay.getYear(), 10);
    cmb_YYYY.setValue(yyyy);
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    url += "&ISUR_CD=" + txb_isur_cd.getValue();
    url += "&EDU_KIND_CD=" + cmb_EDU_KIND_CD.getValue();
    url += "&YYYY=" + cmb_YYYY.getValue();
    url += "&EMP_NO=" + cmb_EMP_NO.getValue();
    url += "&DEP_CD=" + cmb_DEP_CD.getValue();
    url += "&SECU_EDU_TP_CD=" + cmb_edu.getValue(); // 교육구분
    url += "&SCREN_ID=" + "ULDSTF30618.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_MASTER",
        action : "/ListedCompany.do",
        ref : "",
        target : "dts_MASTER=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name getDisclsEduName
 * @description get Discls Edu Name 처리
 * @param {*} gubun gubun
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getDisclsEduName = async function(gubun) {
    const sbmOptions = {
        id : "sbm_dts_EduCrsNm",
        action : "/ListedCompany.do",
        ref : "",
        target : "dts_EduCrsNm=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setVariable
 * @description 자료수정 시 팝업창으로 넘길 데이터 셋팅
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.setVariable = function(row) {
    scwin.key_edu_partc_id = dts_MASTER.getCellData(row, "EDU_PARTC_ID"); // PK
    scwin.key_isur_cd = dts_MASTER.getCellData(row, "ISUR_CD"); // 회사코드
    scwin.key_com_abbrv = dts_MASTER.getCellData(row, "COM_ABBRV"); // 회사명
    scwin.key_chrg_tp_cd = dts_MASTER.getCellData(row, "CHRG_TP_CD"); // 담당자구분코드
    scwin.key_edu_id = dts_MASTER.getCellData(row, "EDU_SCHDL_ID"); // 교육일정코드
    scwin.key_chrg_nm = dts_MASTER.getCellData(row, "CHRG_NM"); // 선택된참가자명
    scwin.key_edu_nm = dts_MASTER.getCellData(row, "DISCLS_EDU_CRS_NM"); // 선택과정명
    scwin.key_edu_ack_tm = dts_MASTER.getCellData(row, "EDU_ACK_TM"); // 이수시간

};

/**
 * @method
 * @name resetVariable
 * @description 자료입력 시 팝업창으로 넘길 데이터 초기화
 * @returns {void}
 * @hidden N
 */
scwin.resetVariable = function() {
    scwin.key_edu_partc_id = ""; // PK
    scwin.key_isur_cd = ""; // 회사코드
    scwin.key_chrg_tp_cd = ""; // 담당자구분코드
    scwin.key_edu_id = ""; // 교육일정코드
    scwin.key_chrg_nm = ""; // 선택된참가자명
    scwin.key_edu_nm = ""; // 선택과정명
    scwin.key_edu_ack_tm = ""; // 이수시간

};

/**
 * @method
 * @name readDisclsEdu
 * @description 입력 또는 수정 팝업창 띄우기
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readDisclsEdu = async function() {
    const options = {
        id: "ULDSTF30625",
        title: "교육참가현황 등록",
        type: "browserPopup",
        width: "860px",
        height: "635px",
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/issueinfo/ULDSTF30625.gfm", options);
};

/**
 * @method
 * @name disclsEduHistory
 * @description 공시담당자 교육참가이력 변경 버튼 클릭 시 팝업창 띄우기
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.disclsEduHistory = async function() {
    const options = {
        id: "ULDSTF30627",
        title: "공시담당자 교육참가이력 변경",
        type: "browserPopup",
        width: "860px",
        height: "635px",
        callbackFn: "scwin.popupCallback"
    };

